options.dotDiagram:
graph ANA_Lab {
    graph [
        layout=dot
        rankdir=TB
        splines=polyline
        nodesep=1.2
        ranksep=1.0
    ];

    node [
        shape=box
        style="rounded,filled"
        fillcolor="lightgray"
        fontname="Arial"
        fontsize=14
        width=1.2
        height=0.6
    ];

    edge [
        fontname="Arial"
        fontsize=10
        penwidth=2
    ];

    R3 [label="R3\nCisco IOS-XE"];
    R4 [label="R4\nCisco IOS-XE"];

    S3 [label="S3\nArista EOS"];
    S4 [label="S4\nNokia SR Linux"];

    R1 [label="R1\nArista EOS"];
    R2 [label="R2\nArista EOS"];

    S1 [label="S1\nArista EOS"];
    S2 [label="S2\nArista EOS"];

    R5 [
        label="R5\nArista EOS\nEdge Router"
        shape=box
        style="rounded,filled"
        fillcolor="#3a3f44"
        fontcolor="white"
    ];

    WEB [
        label="Web Server\nnginx"
        shape=box
        style="rounded,filled"
        fillcolor="#3a3f44"
        fontcolor="white"
    ];

    H1 [
        label="H1\nVLAN 10"
        shape=box
        style="rounded,filled"
        fillcolor="#3a3f44"
        fontcolor="white"
    ];

    H2 [
        label="H2\nVLAN 20"
        shape=box
        style="rounded,filled"
        fillcolor="#3a3f44"
        fontcolor="white"
    ];

    H3 [
        label="H3\nVLAN 10"
        shape=box
        style="rounded,filled"
        fillcolor="#3a3f44"
        fontcolor="white"
    ];

    H4 [
        label="H4\nVLAN 30"
        shape=box
        style="rounded,filled"
        fillcolor="#3a3f44"
        fontcolor="white"
    ];

    { rank=same; R5; }
    { rank=same; R3; R4; }
    { rank=same; S3; S4; }
    { rank=same; R1; R2; }
    { rank=same; S1; S2; }
    { rank=same; H1; H2; H3; H4; }

    // ========================================================
    // eBGP
    // ========================================================

    R5 -- R3 [
        id="CTX-R5-R3"
        color="#777777"
        style=dashed
        xlabel="eBGP"
        fontcolor="#ff4f9a"
        fontsize=10
    ];

    R5 -- R4 [
        id="CTX-R5-R4"
        color="#777777"
        style=dashed
        xlabel="eBGP"
        fontcolor="#ff4f9a"
        fontsize=10
    ];

    // ========================================================
    // OSPFv2 + OSPFv3 - Area 0
    // Actual edge color remains controlled dynamically by Grafana
    // ========================================================

    R3 -- R4 [
        id="R3-R4"
        xlabel="OSPF"
        fontcolor="#4da3ff"
        fontsize=10
    ];

    R3 -- S3 [
        id="R3-S3"
        xlabel="OSPF"
        fontcolor="#4da3ff"
        fontsize=10
    ];

    R4 -- S4 [
        id="R4-S4"
        xlabel="OSPF"
        fontcolor="#4da3ff"
        fontsize=10
    ];

    S3 -- S4 [
        id="S3-S4"
        xlabel="OSPF"
        fontcolor="#4da3ff"
        fontsize=10
    ];

    S3 -- R1 [
        id="R1-S3"
        xlabel="OSPF"
        fontcolor="#4da3ff"
        fontsize=10
    ];

    S4 -- R2 [
        id="R2-S4"
        xlabel="OSPF"
        fontcolor="#4da3ff"
        fontsize=10
    ];

    // ========================================================
    // IS-IS
    // Actual edge color remains controlled dynamically by Grafana
    // ========================================================

    R1 -- S1 [
        id="R1-S1"
        xlabel="IS-IS"
        fontcolor="#39d353"
        fontsize=10
    ];

    R2 -- S2 [
        id="R2-S2"
        xlabel="IS-IS"
        fontcolor="#39d353"
        fontsize=10
    ];

    S1 -- S2 [
        id="S1-S2"
        xlabel="IS-IS"
        fontcolor="#39d353"
        fontsize=10
    ];

    // ========================================================
    // Static context links
    // ========================================================

    R5 -- WEB [
        id="CTX-R5-WEB"
        color="#777777"
    ];

    S1 -- H1 [
        id="CTX-S1-H1"
        color="#777777"
    ];

    S1 -- H2 [
        id="CTX-S1-H2"
        color="#777777"
    ];

    S2 -- H3 [
        id="CTX-S2-H3"
        color="#777777"
    ];

    S2 -- H4 [
        id="CTX-S2-H4"
        color="#777777"
    ];
}

templates:
Link: ${source} ↔ ${target}
Interfaces: ${source_if} ↔ ${target_if}
Status: ${link_status}
RX: ${rx_display}
TX: ${tx_display}
Total: ${total_display}

Vendor: ${vendor}
Management IP: ${mgmt_ip}
CPU: ${cpu_util_pct}%
Memory: ${memory_util_pct}%
Uptime: ${uptime_human}
